<input type="hidden" name="outlets_id" value="{{ $outlet?->outlets_id }}">@if($categories->isEmpty())<p class="admin-help is-warning">Tambahkan kategori sebelum menyimpan menu.</p>@endif<div class="admin-form-grid"><label>Nama menu<input name="name" maxlength="100" required value="{{ old('name', $item?->name) }}"></label><label>Harga (Rp)<input name="price" type="number" min="1" step="1" required value="{{ old('price', $item ? (int) $item->price : '') }}"></label><label>Kategori<select name="menu_categories_id" required>@foreach ($categories as $category)<option value="{{ $category->menu_categories_id }}" @selected(old('menu_categories_id', $item?->menu_categories_id) == $category->menu_categories_id)>{{ $category->name }}</option>@endforeach</select></label><label>Foto menu (JPG, PNG, WebP; maks. 5 MB)<input type="file" name="image" accept="image/jpeg,image/png,image/webp"></label><label class="admin-span-2">Deskripsi<textarea name="description" rows="3" maxlength="5000">{{ old('description', $item?->description) }}</textarea></label></div><label class="admin-checkbox"><input type="checkbox" name="is_available" value="1" @checked(old('is_available', $item?->is_available ?? true))> Menu tersedia untuk dipesan pelanggan</label><div class="admin-form-actions"><button class="admin-button admin-primary" @disabled($categories->isEmpty())>{{ $item ? 'Simpan perubahan' : 'Simpan menu' }}</button>@if($item)<a class="admin-button" href="{{ route('admin.menu.index', ['outlet' => $outlet?->outlets_id]) }}">Batal</a>@else<button class="admin-button" type="button" data-toggle="menu-form">Batal</button>@endif</div>
